
'use strict';
const $=s=>document.querySelector(s);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 10 9-7 9 7v10h-6v-6H9v6H3z"/>',play:'<path d="M4 8h16M4 16h16M8 4v16M16 4v16"/><circle cx="8" cy="8" r="2.9" fill="currentColor"/><circle cx="16" cy="16" r="2.9" fill="currentColor"/>',analysis:'<path d="M3 4v16h18M6 15l5-6 4 3 6-8"/>',friends:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5"/>',book:'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Zm0 0v14"/>',down:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',first:'<path d="M5 5v14m13-14-7 7 7 7"/>',last:'<path d="M19 5v14M6 5l7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',bolt:'<path d="M13 2 4 14h7l-1 8L21 9h-8z"/>',stones:'<circle cx="9" cy="9" r="5"/><path d="M15 8a6 6 0 1 1-7 7"/>',share:'<path d="M9 15l6-6m-8 3-2 2a4 4 0 0 0 6 6l3-3m-4-10 3-3a4 4 0 0 1 6 6l-2 2"/>'};
const icon=(name,small=false)=>`<svg aria-hidden="true" class="${small?'small-icon':'ico'}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]||''}</svg>`;
const get=(k,f)=>{try{return JSON.parse(localStorage.getItem('gobanup.'+k))??f}catch{return f}};
const save=(k,v)=>localStorage.setItem('gobanup.'+k,JSON.stringify(v));
let games=get('games',[]),friends=get('friends',[]),name=get('name','Joueur'),game,position=0,reviewing=false,puzzleMessage='',timer;
const main=$('#main'),modal=$('#modal');
function toast(text){$('#toast').textContent=text;$('#toast').className='show';clearTimeout(timer);timer=setTimeout(()=>$('#toast').className='',3200)}
function popup(title,body){modal.innerHTML=`<button type="button" class="close" aria-label="Fermer" data-action="close">${icon('close')}</button><h2>${title}</h2>${body}`;if(!modal.open)modal.showModal()}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
const routes=[['accueil','home','Accueil'],['jouer','play','Jouer'],['analyse','analysis','Analyse'],['amis','friends','Amis']];
function header(route){$('#nav').innerHTML=routes.map(([key,i,label])=>`<a href="#${key}" class="${key===route?'active':''}" ${key===route?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');$('.help').innerHTML=icon('book');$('#profile').innerHTML=`<span class="avatar">${safe(name[0].toLocaleUpperCase())}</span>${icon('down',true)}`}
function page(title,subtitle='',action=''){return `<div class="page-title"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`}
function btn(label,act,i='',primary=false){return `<button class="btn ${primary?'primary':''}" data-action="${act}">${i?icon(i):''}${label}</button>`}
function newGame(n,mode,opponent){return {id:crypto.randomUUID(),n,mode,opponent,moves:[],date:Date.now()}}
function saveGame(){games=[game,...games.filter(g=>g.id!==game.id)].slice(0,80);save('games',games)}
const demos=[{id:'opening',title:'Les premiers coups',n:19,moves:[60,300,72,288,244,270,41,319,110,249]},{id:'atari',title:'Comprendre l’atari',n:9,moves:[39,40,31,50,41,51,49]}];
function gameTitle(g){return g.title||({bot:'Partie rapide',local:'Partie à deux',link:'Partie par correspondance'}[g.mode]||'Étude libre')}
function makeStates(g){let board=g.start?g.start.slice():Array(g.n*g.n).fill(0);const states=[board],caps=[[0,0]];for(let i=0;i<g.moves.length;i++){let cap=caps[i].slice();if(g.moves[i]!==-1){const r=Go.play(board,g.moves[i],i%2+1,g.n,states);if(!r)throw Error('Coup incorrect');board=r.board;cap[i%2]+=r.captured}states.push(board);caps.push(cap)}return {states,caps}}
const ended=g=>g.moves.length>=2&&g.moves.slice(-2).every(m=>m===-1);
const coord=(p,n)=>p===-1?'Passe':'ABCDEFGHJKLMNOPQRST'[p%n]+(n-Math.floor(p/n));
function boardSvg(board,n,last=-1,keys=false){const e=12,side=100,gap=(side-2*e)/(n-1),axis=v=>e+v*gap,rad=gap*.455;let lines='',dots='',stones='',labels='';
for(let i=0;i<n;i++){const v=axis(i);lines+=`M${v} ${e}V${side-e}M${e} ${v}H${side-e}`;if(keys)labels+=`<text x="${v}" y="6.5">${'ABCDEFGHJKLMNOPQRST'[i]}</text><text x="5.6" y="${v+1.05}">${n-i}</text>`}
const marks=n===9?[2,4,6]:n===13?[3,6,9]:[3,9,15];for(const i of marks)for(const j of marks)if(n===19||(i===marks[1])===(j===marks[1]))dots+=`<circle cx="${axis(i)}" cy="${axis(j)}" r="${gap*.115}"/>`;
board.forEach((v,i)=>{if(!v)return;const x=axis(i%n),y=axis(Math.floor(i/n));stones+=`<circle cx="${x+.28}" cy="${y+.5}" r="${rad}" fill="#5b402b66"/><circle cx="${x}" cy="${y}" r="${rad}" fill="${v===1?'url(#stoneB)':'url(#stoneW)'}" stroke="${v===1?'#161714':'#dbd4c4'}" stroke-width=".18"/>`;if(last===i)stones+=`<circle cx="${x}" cy="${y}" r="${rad*.34}" fill="none" stroke="${v===1?'#eee':'#4a493e'}" stroke-width="${gap*.09}"/>`});
return `<svg viewBox="0 0 100 100" aria-hidden="true"><defs><radialGradient id="stoneB" cx="34%" cy="24%" r="77%"><stop stop-color="#54554e"/><stop offset=".55" stop-color="#282a26"/><stop offset="1" stop-color="#141513"/></radialGradient><radialGradient id="stoneW" cx="34%" cy="24%" r="77%"><stop stop-color="#fffef6"/><stop offset=".72" stop-color="#f0ecdf"/><stop offset="1" stop-color="#d6d0c0"/></radialGradient></defs><path d="${lines}" fill="none" stroke="#745934" stroke-width="${n===19?.16:.28}"/><g fill="#5d482d">${dots}</g><g fill="#665136" font-family="sans-serif" font-size="${n===19?2.2:3}" text-anchor="middle">${labels}</g>${stones}</svg>`}
const startPuzzle=()=>{const b=Array(81).fill(0);[22,30,39,49,50].forEach(i=>b[i]=1);[31,40,41,32].forEach(i=>b[i]=2);[23,33].forEach(i=>b[i]=1);return b};
function art(kind){let shapes='';if(kind==='quick'){
for(let i=0;i<7;i++)shapes+=`<path d="M${i*21} 0v134M0 ${i*21}h140"/>`;
shapes=`<g transform="translate(24,32) rotate(-12 60 50)"><g stroke="#b5b6a4" opacity=".64" fill="none">${shapes}</g><circle cx="63" cy="42" r="13.6" fill="#1e2320"/><circle cx="84" cy="63" r="13.6" fill="#f6f3e8" stroke="#b0afa2"/><circle cx="63" cy="84" r="13.6" fill="#292c26"/><circle cx="105" cy="42" r="13.6" fill="#252a25"/></g>`;
}else if(kind==='friend'){shapes=`<g transform="rotate(-14 78 70)"><g fill="none" stroke="#c4cdbb"><ellipse cx="86" cy="66" rx="62" ry="36"/><ellipse cx="86" cy="66" rx="72" ry="44"/><ellipse cx="86" cy="66" rx="82" ry="52"/></g><ellipse cx="61" cy="71" rx="25" ry="22" fill="#a9ae9c"/><ellipse cx="60" cy="67" rx="25" ry="22" fill="#f5f4e9" stroke="#bbbfb0"/><ellipse cx="102" cy="57" rx="25" ry="22" fill="#101713"/><ellipse cx="102" cy="53" rx="25" ry="22" fill="#333a32"/></g>`}else{for(let i=0;i<8;i++)shapes+=`<path d="M${i*18} 12v115M6 ${i*18+12}h135"/>`;shapes=`<g transform="translate(16,5) rotate(-9 65 65)"><g stroke="#b5c6cf" opacity=".55">${shapes}</g><path d="m0 94 28-15 17 7 23-37 20 10 42-38" fill="none" stroke="#56798c" stroke-width="2.8"/>${[[28,79],[45,86],[68,49],[88,59]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4.6" fill="#f3f6f5" stroke="#56798c" stroke-width="2"/>`).join('')}</g>`}
return `<svg class="art" viewBox="0 0 140 140" preserveAspectRatio="xMaxYMid slice" aria-hidden="true">${shapes}</svg>`}
function studyRow(title,meta,action){return `<button class="study" data-action="${action}"><span class="stone-pair"></span><span><strong>${safe(title)}</strong><span class="meta">${safe(meta)}</span></span><span class="end">${icon('right',true)}</span></button>`}
function home(){const actions=[['quick','red','bolt','Partie rapide','Affrontez l’ordinateur.','quick'],['friend','green','friends','Défier un ami','Invitez un partenaire de jeu.','challenge'],['review','blue','analysis','Analyser','Explorez chaque coup.','library']];
main.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">LE CLUB DE GO</div><h1>À vous de jouer.</h1><p>Une partie, un ami, un nouveau défi.<br>Retrouvez tout votre go au même endroit.</p>${btn('Nouvelle partie','new','play',true)}</div></section><section class="block"><div class="section-title"><h2>Accès rapide</h2></div><div class="quick-grid">${actions.map(([k,c,i,t,d,a])=>`<button class="quick" data-action="${a}">${art(k)}<span class="tile-icon ${c}">${icon(i)}</span><strong>${t}</strong><span class="desc">${d}</span></button>`).join('')}</div></section><div class="lower"><section class="block"><div class="section-title"><h2>Le coin tsumego</h2></div><div class="panel puzzle-card"><div class="mini-board">${boardSvg(startPuzzle(),9)}</div><div class="puzzle-content"><span class="chip">Débutant</span><h3>Capture en un coup</h3><div class="meta">Noir joue · Goban 9 × 9</div>${btn('Résoudre le problème','puzzle')}</div></div></section><section class="block"><div class="section-title"><h2>Carnet d’analyse</h2><button class="text-btn" data-action="library">Tout voir</button></div><div class="panel">${(games.length?games.slice(0,2):demos).map(g=>studyRow(gameTitle(g),`${g.n} × ${g.n} · ${g.moves.length} coups`,'review:'+g.id)).join('')}</div></section></div>`}
function library(){main.innerHTML=page('Analyse','Rejouez vos parties et testez vos variantes.',btn('Étude libre','free','plus',true))+`<div class="library">${games.length?`<section class="block"><div class="section-title"><h2>Mes parties et études</h2></div><div class="panel">${games.map(g=>studyRow(gameTitle(g),`${g.n} × ${g.n} · ${g.moves.length} coups`,'review:'+g.id)).join('')}</div></section>`:''}<section class="block"><div class="section-title"><h2>Études du club</h2></div><div class="panel">${demos.map(g=>studyRow(g.title,`Goban ${g.n} × ${g.n} · ${g.moves.length} coups`,'review:'+g.id)).join('')}</div></section></div>`}
function friendsPage(){main.innerHTML=page('Amis','Votre carnet de partenaires, enregistré sur cet appareil.',btn('Ajouter un ami','add','plus',true))+`<div class="panel library">${friends.length?friends.map((f,i)=>`<div class="friend-row"><span class="avatar">${safe(f[0].toUpperCase())}</span><strong>${safe(f)}</strong>${btn('Défier','challenge:'+i,'stones')}</div>`).join(''):'<div class="empty">Ajoutez le pseudo d’un ami pour lui proposer une partie.</div>'}</div>`}
function lobby(){main.innerHTML=page('Jouer','Choisissez votre goban et votre adversaire.',btn('Nouvelle partie','new','plus',true))+`<div class="panel library">${studyRow('Partie rapide','Jouer contre l’ordinateur sur un goban 9 × 9.','quick')}${studyRow('Jouer à deux','Partager le même goban sur cet appareil.','local')}${studyRow('Jouer par correspondance','Transmettre la position à un ami par lien.','challenge')}</div>${games.filter(g=>!ended(g)&&g.mode!=='study').length?`<section class="block library"><div class="section-title"><h2>Reprendre une partie</h2></div><div class="panel">${games.filter(g=>!ended(g)&&g.mode!=='study').map(g=>studyRow(gameTitle(g),`${g.moves.length} coups`,'resume:'+g.id)).join('')}</div></section>`:''}`}
function startForm(mode='bot',opponent=''){popup(mode==='link'?'Défier un ami':'Nouvelle partie',`<form id="setup"><label for="mode">Adversaire</label><select id="mode"><option value="bot">Ordinateur</option><option value="local">Deux joueurs sur cet appareil</option><option value="link">Ami par correspondance</option></select><fieldset><legend>Taille du goban</legend><div class="options">${[9,13,19].map(n=>`<label><input type="radio" name="size" value="${n}" ${n===9?'checked':''}><span>${n} × ${n}</span></label>`).join('')}</div></fieldset><div id="inviteFields"><label for="opponent">Pseudo de votre ami</label><input id="opponent" maxlength="32" value="${safe(opponent)}" placeholder="Partenaire"><p class="note">Jouez votre coup, puis envoyez le lien de la position à votre ami. Il vous répondra avec le sien.</p></div><button class="btn primary" type="submit">Commencer la partie</button></form>`);$('#mode').value=mode;const fields=()=>$('#inviteFields').hidden=$('#mode').value!=='link';$('#mode').onchange=fields;fields();$('#setup').onsubmit=e=>{e.preventDefault();launch(newGame(Number(new FormData(e.target).get('size')),$('#mode').value,$('#opponent').value.trim()||'Partenaire'))}}
function launch(g){game=g;if(g.mode==='link')game.seat=1;saveGame();modal.close();location.hash='partie/'+g.id}
function readGame(id){return games.find(g=>g.id===id)||demos.find(g=>g.id===id)}
function shareUrl(){const {id,n,moves,opponent}=game;const payload={id,n,moves,opponent:game.seat===1?name:opponent,seat:3-game.seat};return location.href.split('#')[0]+'#invitation/'+encodeURIComponent(JSON.stringify(payload))}
function share(){popup('Transmettre la partie',`<p>Envoyez ce lien à votre partenaire pour qu’il ouvre le goban et joue son coup.</p><label for="url">Lien de la position</label><textarea id="url" readonly rows="3">${safe(shareUrl())}</textarea><div class="actions">${btn('Copier le lien','copy','share',true)}</div>`)}
function receive(raw){try{const data=JSON.parse(decodeURIComponent(raw));const {id,n,moves,seat}=data;if(!/^[a-f0-9-]{36}$/.test(id)||![9,13,19].includes(n)||![1,2].includes(seat)||!Array.isArray(moves)||moves.length>3000||!moves.every(p=>Number.isInteger(p)&&p>=-1&&p<n*n))throw Error();const old=games.find(g=>g.id===id);let g={id,n,moves,seat,mode:'link',date:Date.now(),opponent:String(data.opponent||'Partenaire').slice(0,32)};makeStates(g);if(old){if(old.mode!=='link'||old.n!==n||!moves.slice(0,Math.min(old.moves.length,moves.length)).every((m,i)=>old.moves[i]===m))throw Error();if(old.moves.length>=moves.length||old.seat!==seat)g=old}game=g;saveGame();location.replace('#partie/'+id)}catch{toast('Ce lien de partie est invalide.');location.replace('#jouer')}}
function drawGame(){const {states,caps}=makeStates(game),n=game.n,b=states[position],color=position%2+1,finished=ended(game),isPuzzle=game.mode==='puzzle',interactive=!reviewing&&!finished&&(!isPuzzle||!game.moves.length)&&(game.mode!=='bot'||color===1)&&(game.mode!=='link'||game.seat===color);let dots='';
if(interactive){for(let p=0;p<b.length;p++){if(b[p])continue;const scale=76/(n-1);dots+=`<button style="left:${12+(p%n)*scale}%;top:${12+Math.floor(p/n)*scale}%;width:${scale}%;height:${scale}%" data-point="${p}" aria-label="Jouer en ${coord(p,n)}"></button>`}}
const title=isPuzzle?'Capture en un coup':gameTitle(game);const titleAct=reviewing?btn('Carnet d’analyse','library','book'):!isPuzzle?btn('Nouvelle partie','new','plus'):'';
const score=finished?Go.score(b,n):null;const status=finished?`Score sur le goban · Noir ${score[1]} / Blanc ${String(score[2]).replace('.',',')}`:isPuzzle?(game.moves.length?'Problème résolu':'Noir doit capturer'):color===1?'Aux noirs de jouer':'Aux blancs de jouer';
main.innerHTML=page(safe(title),`${n} × ${n} · ${isPuzzle?'Tsumego débutant':reviewing?'Analyse de la position':game.mode==='link'?'Par correspondance':game.mode==='bot'?'Contre l’ordinateur':game.mode==='study'?'Analyse libre':'Sur cet appareil'}`,titleAct)+`<div class="game-layout"><div class="board-wrap"><div class="board" aria-label="Goban ${n} par ${n}">${boardSvg(b,n,game.moves[position-1],true)}${dots}</div></div><aside class="panel side"><h2>${reviewing?'Naviguer dans la partie':isPuzzle?'Le problème':'La partie'}</h2><div class="turn"><i class="stone ${color===2?'white':''}"></i>${status}</div>${isPuzzle?`<p>Le groupe blanc n’a plus qu’une liberté. Trouvez l’intersection qui permet de le capturer.</p><div class="puzzle-msg" role="status">${puzzleMessage}</div><div class="actions">${btn('Recommencer','resetPuzzle')}${btn('Accueil','home')}</div>`:`<p>Coup ${position}${position?' · '+coord(game.moves[position-1],n):''}<br>Captures · Noir ${caps[position][0]} / Blanc ${caps[position][1]}</p>${reviewing?`<div class="line"></div><div class="move-nav">${[['first',0],['left',Math.max(0,position-1)],['right',Math.min(game.moves.length,position+1)],['last',game.moves.length]].map(([i,d],ix)=>`${ix===2?`<span>${position} / ${game.moves.length}</span>`:''}<button class="btn" aria-label="${['Début','Coup précédent','Coup suivant','Fin'][ix]}" data-action="step:${d}" ${d===position?'disabled':''}>${icon(i,true)}</button>`).join('')}</div><input aria-label="Position dans la partie" type="range" min="0" max="${game.moves.length}" value="${position}" id="slider"><div class="actions">${btn('Tester une variante','branch','analysis')}</div>`:`<div class="line"></div>${game.mode==='link'?`<p>${game.seat===color&&!finished?'À vous de jouer.':'Transmettez la position à votre partenaire.'}</p>`:''}<div class="actions">${interactive?btn('Passer','pass'):''}${game.mode==='link'&&(game.seat!==color||finished)?btn('Transmettre le lien','share','share',true):''}${btn('Analyser','review:'+game.id,'analysis')}</div>`}`}</aside></div>`;if($('#slider'))$('#slider').oninput=e=>{position=+e.target.value;drawGame();$('#slider').focus()}}
function move(p){const st=makeStates(game).states,color=game.moves.length%2+1;if(ended(game)||reviewing||game.mode==='link'&&game.seat!==color)return;const result=p===-1?null:Go.play(st.at(-1),p,color,game.n,st);if(p!==-1&&!result){toast('Coup interdit sur cette intersection.');return}if(game.mode==='puzzle'){if(!result?.captured){puzzleMessage='Essayez une autre intersection.';drawGame();return}puzzleMessage='Bien joué ! Les quatre pierres blanches sont capturées.'}game.moves.push(p);
if(game.mode==='bot'&&!ended(game)){const boards=makeStates(game).states,b=boards.at(-1);let best=-Infinity,choice=-1;if(p!==-1){for(let q=0;q<b.length;q++){const r=Go.play(b,q,2,game.n,boards);if(!r)continue;const g=Go.group(r.board,q,game.n);const adj=Go.adjacent(q,game.n);if(adj.every(v=>b[v]===2)&&!r.captured)continue;const score=r.captured*12+Math.random()*4+adj.filter(i=>b[i]===1).length*.7+(g.liberties.size===1?-7:0)-Math.abs((q%game.n)-(game.n-1)/2)*.06;if(score>best){best=score;choice=q}}}game.moves.push(choice)}
position=game.moves.length;if(game.mode!=='puzzle')saveGame();drawGame()}
function route(){modal.close();const hash=location.hash.slice(1)||'accueil',sep=hash.indexOf('/'),key=sep<0?hash:hash.slice(0,sep),id=sep<0?'':hash.slice(sep+1);reviewing=false;header(key==='partie'||key==='probleme'?'jouer':key==='etude'?'analyse':key);if(key==='invitation'){receive(id);return}if(key==='partie'||key==='etude'){game=readGame(id);if(!game){location.replace('#jouer');return}reviewing=key==='etude';position=game.moves.length;drawGame()}else if(key==='probleme'){game={n:9,start:startPuzzle(),moves:[],mode:'puzzle'};position=0;puzzleMessage='';drawGame()}else if(key==='jouer')lobby();else if(key==='amis')friendsPage();else if(key==='analyse')library();else home();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const point=e.target.closest('[data-point]');if(point){move(+point.dataset.point);return}const el=e.target.closest('[data-action]');if(!el)return;const [a,id]=el.dataset.action.split(':');
if(a==='close'){modal.close();return}if(a==='new'||a==='local')startForm(a==='local'?'local':'bot');if(a==='quick')launch(newGame(9,'bot','Ordinateur'));if(a==='challenge')startForm('link',id!==undefined?friends[+id]:'');if(a==='puzzle')location.hash='probleme';if(a==='resetPuzzle')route();if(a==='library')location.hash='analyse';if(a==='home')location.hash='accueil';if(a==='resume')location.hash='partie/'+id;if(a==='review')location.hash='etude/'+id;if(a==='step'){position=+id;drawGame()}if(a==='free')launch(newGame(19,'study',''));if(a==='branch'){const g=newGame(game.n,'study','');g.title='Variante · '+gameTitle(game).replace(/^Variante · /,'');g.moves=game.moves.slice(0,position);launch(g)}if(a==='pass')move(-1);if(a==='share')share();if(a==='copy'){navigator.clipboard?.writeText($('#url').value).then(()=>toast('Lien copié.')).catch(()=>$('#url').select());$('#url').select()}
if(a==='profile'||a==='add'){const profile=a==='profile';popup(profile?'Mon profil':'Ajouter un ami',`<form id="identity"><label for="nickname">${profile?'Votre pseudo':'Pseudo du partenaire'}</label><input id="nickname" maxlength="32" required value="${profile?safe(name):''}" autocomplete="off"><p class="note">${profile?'Ce profil est enregistré sur cet appareil.':'Ce partenaire sera ajouté à votre carnet sur cet appareil.'}</p><button type="submit" class="btn primary">${profile?'Enregistrer':'Ajouter au carnet'}</button></form>`);$('#identity').onsubmit=ev=>{ev.preventDefault();const value=$('#nickname').value.trim();if(!value)return;if(profile){name=value;save('name',name)}else{if(friends.some(f=>f.toLocaleLowerCase()===value.toLocaleLowerCase())){$('#nickname').setCustomValidity('Ce partenaire figure déjà dans votre carnet.');$('#nickname').reportValidity();$('#nickname').oninput=()=>$('#nickname').setCustomValidity('');return}friends.push(value);save('friends',friends)}modal.close();if(profile){$('#profile .avatar').textContent=name[0].toUpperCase()}else friendsPage();toast(profile?'Profil enregistré.':'Partenaire ajouté.')}}if(a==='rules')popup('Les règles du go','<ol class="rules"><li>Noir commence. À tour de rôle, posez une pierre sur une intersection libre.</li><li>Les pierres de même couleur reliées horizontalement ou verticalement forment un groupe. Ses intersections libres voisines sont ses libertés.</li><li>Entourez un groupe adverse pour lui retirer sa dernière liberté et le capturer.</li><li>Le suicide et la répétition d’une position sont interdits.</li><li>Deux passes consécutives terminent la partie. Le score compte les pierres et les intersections entourées. Blanc reçoit 6,5 points de komi. Capturez les pierres mortes avant de passer.</li></ol>')});
window.addEventListener('hashchange',route);route();

